export function generateSteps(input) {
  const { arr, target } = input;
  const n = arr.length;

  // Validate input array is sorted
  for (let i = 1; i < n; i++) {
    if (arr[i] < arr[i - 1]) {
      return [{
        type: 'error',
        msg: `❌ Error: Array must be sorted!`,
        indices: [],
        arr: [...arr],
        comparisons: 0,
        jumps: 0,
      }];
    }
  }

  const jumpSize = Math.floor(Math.sqrt(n));
  const steps = [];
  let comparisons = 0;
  let jumps = 0;

  steps.push({
    type: 'info',
    msg: `Searching for ${target} | Size: ${n}, Jump: √${n} = ${jumpSize}`,
    indices: [],
    arr: [...arr],
    comparisons,
    jumps,
  });

  // Phase 1: Find the block
  let prev = 0;
  let curr = jumpSize;

  while (curr < n && arr[curr] < target) {
    comparisons++;
    jumps++;

    steps.push({
      type: 'jump',
      msg: `Jump to index ${curr}. Value ${arr[curr]} < target ${target}`,
      indices: [curr],
      blockStart: prev,
      blockEnd: curr,
      arr: [...arr],
      comparisons,
      jumps,
    });

    prev = curr;
    curr += jumpSize;
  }

  // Phase 2: Linear search within the block
  const blockEnd = Math.min(curr, n - 1);
  steps.push({
    type: 'block_found',
    msg: `Block found: indices ${prev}–${blockEnd}. Starting linear search...`,
    indices: [],
    blockStart: prev,
    blockEnd: blockEnd,
    arr: [...arr],
    comparisons,
    jumps,
  });

  let found = false;
  for (let i = prev; i < Math.min(curr, n); i++) {
    comparisons++;

    // Early exit: if current element is greater than target, target doesn't exist
    if (arr[i] > target) {
      steps.push({
        type: 'search',
        msg: `Checking index ${i}. Value ${arr[i]} > target ${target}. Target not in array.`,
        indices: [i],
        blockStart: prev,
        blockEnd: Math.min(curr, n - 1),
        arr: [...arr],
        comparisons,
        jumps,
      });
      break;
    }

    if (arr[i] === target) {
      steps.push({
        type: 'found',
        msg: `✅ Found ${target} at index ${i}!`,
        indices: [i],
        found: true,
        arr: [...arr],
        comparisons,
        jumps,
      });
      found = true;
      break;
    } else {
      steps.push({
        type: 'search',
        msg: `Checking index ${i}. Value ${arr[i]} < target ${target}`,
        indices: [i],
        blockStart: prev,
        blockEnd: Math.min(curr, n - 1),
        arr: [...arr],
        comparisons,
        jumps,
      });
    }
  }

  if (!found) {
    steps.push({
      type: 'not_found',
      msg: `❌ Target ${target} not found in array`,
      indices: [],
      arr: [...arr],
      comparisons,
      jumps,
    });
  }

  return steps;
}
